import pytest


def age_at(born: int, now: int) -> int:
    """Whole years between birth year `born` and current year `now`.

    Only years are compared, so the result is `now - born`. The clock is
    never read; `now` is always supplied by the caller.

    Raises ValueError if `now` is earlier than `born`.
    """
    if now < born:
        raise ValueError(f"now ({now}) is earlier than born ({born})")
    return now - born


def test_age_typical() -> None:
    assert age_at(2000, 2024) == 24
    assert age_at(1990, 2025) == 35


def test_age_same_year_is_zero() -> None:
    assert age_at(2024, 2024) == 0


def test_age_one_year() -> None:
    assert age_at(2023, 2024) == 1


def test_age_long_span() -> None:
    assert age_at(1900, 2024) == 124


def test_age_before_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2025, 2024)


def test_age_just_before_birth_raises() -> None:
    with pytest.raises(ValueError):
        age_at(2001, 2000)

